CREATE TABLE universe_definitions(universe_id uuid PRIMARY KEY,name text NOT NULL,kind text NOT NULL,source text NOT NULL,version text NOT NULL,rule_description text NOT NULL,max_change_ratio numeric NOT NULL CHECK(max_change_ratio BETWEEN 0 AND 1),max_staleness_days integer NOT NULL CHECK(max_staleness_days>=0),UNIQUE(name,version));
CREATE TABLE universe_batches(batch_id uuid PRIMARY KEY,universe_id uuid NOT NULL REFERENCES universe_definitions,source_batch_id text NOT NULL,effective_date date NOT NULL,announced_at timestamptz NOT NULL,available_at timestamptz NOT NULL,payload_hash text NOT NULL,status text NOT NULL,member_count integer NOT NULL CHECK(member_count>=0),UNIQUE(universe_id,source_batch_id),CHECK(available_at>=announced_at));
CREATE TABLE universe_memberships(membership_id uuid PRIMARY KEY,universe_id uuid NOT NULL REFERENCES universe_definitions,instrument_id uuid NOT NULL REFERENCES instruments,valid_from date NOT NULL,valid_to date,announced_at timestamptz NOT NULL,available_at timestamptz NOT NULL,source_batch_id text NOT NULL,CHECK(valid_to IS NULL OR valid_to>valid_from),CHECK(available_at>=announced_at));
CREATE EXTENSION IF NOT EXISTS btree_gist;
ALTER TABLE universe_memberships ADD CONSTRAINT no_universe_member_overlap EXCLUDE USING gist(universe_id WITH =,instrument_id WITH =,daterange(valid_from,valid_to,'[)') WITH &&);
CREATE TABLE classification_memberships(classification_id uuid PRIMARY KEY,instrument_id uuid NOT NULL REFERENCES instruments,provider text NOT NULL,system text NOT NULL,version text NOT NULL,level integer NOT NULL,code text NOT NULL,name text NOT NULL,valid_from date NOT NULL,valid_to date,available_at timestamptz NOT NULL);
CREATE TABLE universe_snapshots(snapshot_id uuid PRIMARY KEY,universe_id uuid NOT NULL REFERENCES universe_definitions,decision_at timestamptz NOT NULL,data_snapshot_id uuid NOT NULL,member_ids jsonb NOT NULL,member_hash char(64) NOT NULL,source_batch_ids jsonb NOT NULL);
CREATE TABLE universe_quality_results(result_id uuid PRIMARY KEY,batch_id uuid NOT NULL,code text NOT NULL,message text NOT NULL,source_code text);
CREATE TABLE universe_events(event_id uuid PRIMARY KEY,universe_id uuid NOT NULL,batch_id uuid NOT NULL,joined jsonb NOT NULL,removed jsonb NOT NULL,effective_date date NOT NULL,occurred_at timestamptz NOT NULL);
